import {localizeMarkup} from './i18n.js';
import {searchPanel,assistantWidget} from './engagement.js';
import {escapeHTML as E,money} from './core.js';
export {E,money};
const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M2 21v-2a7 7 0 0 1 14 0v2M16 5a3 3 0 0 1 0 6m3 10v-3a5 5 0 0 0-3-4"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',home:'<path d="m3 10 9-7 9 7v11h-6v-8H9v8H3V10Z"/>',box:'<path d="m12 3 9 5v9l-9 5-9-5V8l9-5Z"/><path d="m3 8 9 5 9-5M12 13v9M7 5l10 6"/>',layers:'<path d="m12 3 10 5-10 5L2 8l10-5Zm-10 10 10 5 10-5M2 18l10 5 10-5"/>',cart:'<path d="M2 3h3l3 13h11l3-10H6"/><circle cx="9" cy="21" r="1"/><circle cx="18" cy="21" r="1"/>',truck:'<path d="M2 5h12v12H2V5Zm12 5h5l3 4v3h-8"/><circle cx="6" cy="19" r="2"/><circle cx="18" cy="19" r="2"/>',wallet:'<rect x="3" y="5" width="19" height="16" rx="2"/><path d="M3 8V4l15-2v3M16 11h6v6h-6v-6Z"/>',card:'<rect x="2" y="4" width="20" height="16" rx="3"/><path d="M2 9h20M6 15h4"/>',chart:'<path d="M4 21V11h4v10M10 21V3h4v18M16 21V8h4v13"/>',tag:'<path d="M3 3h9l10 10-9 9L3 12V3Z"/><circle cx="8" cy="8" r="1"/>',file:'<path d="M5 2h10l4 4v16H5V2Zm10 0v5h4M8 11h8M8 15h8M8 19h5"/>',settings:'<path d="m12 3 2 2 3-.3.3 3 2 2-2 2 .3 3-3 .3-2 2-2-2-3 .3-.3-3-2-2 2-2-.3-3 3-.3 2-2Z"/><circle cx="12" cy="10" r="3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',return:'<path d="m7 3-5 5 5 5M2 8h12a7 7 0 0 1 0 14h-3"/>',plus:'<path d="M12 4v16M4 12h16"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m5 5 14 14M5 19 19 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0v7l-2 3h16l-2-3V8ZM10 21h4"/>',edit:'<path d="m14 5 5 5M3 21l2-7L17 2l5 5L10 19l-7 2Z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',lock:'<rect x="4" y="10" width="16" height="12" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',map:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="3"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 5 10 8L22 5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',logout:'<path d="M10 3H3v18h7M8 12h14m-5-5 5 5-5 5"/>',filter:'<path d="M3 4h18l-7 8v8l-4-2v-6L3 4Z"/>',image:'<rect x="2" y="3" width="20" height="18" rx="2"/><circle cx="8" cy="9" r="2"/><path d="m2 19 6-6 4 4 4-5 6 7"/>'};
export const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.file}</svg>`;
export const badge=(v,style='')=>`<span class="badge ${style}">${E(v)}</span>`;
export const link=(label,to,cls='btn')=>`<a class="${cls}" href="#${to}">${label}</a>`;
export const button=(label,action,attrs='',cls='btn')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
export const field=(label,name,value='',type='text',extra='')=>`<label class="field"><span>${E(label)}</span><input name="${name}" type="${type}" value="${E(value)}" ${extra}></label>`;
export const select=(label,name,options,value='',extra='')=>`<label class="field"><span>${E(label)}</span><select name="${name}" ${extra}>${options.map(o=>{const v=Array.isArray(o)?o[0]:o,t=Array.isArray(o)?o[1]:o;return `<option value="${E(v)}" ${v===value?'selected':''}>${E(t)}</option>`}).join('')}</select></label>`;
export const textarea=(label,name,value='',extra='')=>`<label class="field"><span>${E(label)}</span><textarea name="${name}" ${extra}>${E(value)}</textarea></label>`;
export const checkbox=(label,name,checked=false)=>`<label class="checkbox"><input type="checkbox" name="${name}" ${checked?'checked':''}><span>${E(label)}</span></label>`;
export const table=(heads,rows,foot='')=>`<div class="card no-pad"><div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}"><div class="empty">No matching records.</div></td></tr>`}</tbody></table></div>${foot?`<div class="table-foot">${foot}</div>`:''}</div>`;
export const stat=(label,value,sub='',name='chart',inverse=false)=>`<div class="stat ${inverse?'inverse':''}"><div class="stat-label">${E(label)}${icon(name)}</div><div class="stat-value">${value}</div><small>${E(sub)}</small></div>`;
export const notice=(message)=>`<div class="notice">${message}</div>`;
export const empty=(title,message,to='/shop',cta='Explore the collection',name='bag')=>`<div class="empty">${icon(name)}<h2>${E(title)}</h2><p>${E(message)}</p>${to?link(cta,to):''}</div>`;
export const heading=(title,desc='',actions='')=>`<div class="admin-heading"><div><h1>${E(title)}</h1>${desc?`<p>${E(desc)}</p>`:''}</div><div class="actions">${actions}</div></div>`;
export const tabs=(items,current,base)=>`<div class="tabs">${items.map(([id,title])=>link(E(title),base+id,id===current?'active':'')).join('')}</div>`;
export const previewBar=()=>`<div class="preview-bar"><span class="preview-label">Interactive preview · Sample data</span><nav class="preview-links" aria-label="Preview areas"><a href="#/">Storefront</a><a href="#/admin">Admin</a><a href="#/install">Installer</a></nav></div>`;
export const wordmark=()=>'<span class="wordmark">AELVO<small>FASHION</small></span>';
export function mobileNav(isAdmin,path,state){const items=isAdmin?[['Overview','/admin','grid'],['Orders','/admin/orders','bag'],['Stock','/admin/inventory','layers'],['Accounts','/admin/accounts','wallet'],['More','menu','menu']]:[['Home','/','home'],['Shop','/shop','grid'],['Bag','/cart','bag'],['Wishlist','/wishlist','heart'],['Account','/account','user']];let active=items.findIndex((x,i)=>x[1]===path||(i&&path.startsWith(x[1]+'/')));if(active<0)active=isAdmin?4:1;const previous=state.mobileLast?.scope===isAdmin?state.mobileLast.index:active;state.mobileLast={scope:isAdmin,index:active};return `<nav class="mobile-nav" style="--active:${active};--from:${previous}" aria-label="${isAdmin?'Admin':'Store'} navigation">${items.map(([label,to,img],i)=>to==='menu'?`<button type="button" data-action="admin-menu" class="${i===active?'active':''}">${icon(img)}<span>${label}</span></button>`:`<a class="${i===active?'active':''} ${!isAdmin&&to==='/cart'?'center-bag':''}" href="#${to}">${icon(img)}<span>${label}${label==='Bag'&&state.cart.length?' · '+state.cart.reduce((n,r)=>n+r.qty,0):''}</span></a>`).join('')}</nav>`}
export function storeShell(content,state,path){return localizeMarkup(`${previewBar()}<header class="store-header"><a href="#/" aria-label="AELVO home">${wordmark()}</a><nav class="store-nav" aria-label="Store navigation"><a href="#/shop" class="${path==='/shop'?'selected':''}">Shop all</a><a href="#/shop?category=Shoes">Shoes</a><a href="#/shop?category=Bags">Bags</a><a href="#/shop?category=Wallets">Accessories</a><a href="#/about">Our story</a></nav><div class="header-actions"><div class="language-switch" aria-label="Language"><button type="button" data-action="set-language" data-value="bn" lang="bn" aria-pressed="${state.language==='bn'}">বাংলা</button><button type="button" data-action="set-language" data-value="en" lang="en" aria-pressed="${state.language!=='bn'}">EN</button></div><button class="icon-btn" type="button" data-action="open-search" aria-controls="header-search" aria-expanded="${!!state.searchOpen}" aria-label="Search">${icon('search')}</button><a class="icon-btn desktop-only" href="#/account" aria-label="My account">${icon('user')}</a><a class="icon-btn" href="#/wishlist" aria-label="Wishlist">${icon('heart')}${state.wishlist.length?`<span class="count">${state.wishlist.length}</span>`:''}</a><a class="icon-btn" href="#/cart" aria-label="Shopping bag">${icon('bag')}${state.cart.length?`<span class="count">${state.cart.reduce((n,r)=>n+r.qty,0)}</span>`:''}</a></div></header>${searchPanel(state)}<main id="main" class="page-enter">${content}</main><footer class="store-footer"><div class="footer-grid"><div><a href="#/">${wordmark()}</a><p>Considered essentials for everyday life.</p></div><div><h4>Explore</h4><a href="#/shop?category=Shoes">Shoes</a><a href="#/shop?category=Bags">Bags</a><a href="#/shop?category=Wallets">Wallets</a><a href="#/wishlist">Your wishlist</a></div><div><h4>Here to help</h4><a href="#/help">Help & FAQ</a><a href="#/tracking">Track an order</a><a href="#/contact">Contact us</a><a href="#/account/returns">Returns</a></div><div><h4>The details</h4><a href="#/about">About AELVO</a><a href="#/policy/shipping">Shipping policy</a><a href="#/policy/privacy">Privacy & terms</a><a href="#/policy/returns">Return policy</a></div></div><div class="footer-bottom"><span>© 2026 AELVO Fashion</span><span>Bangladesh · BDT</span><span>Design preview · No real orders or payments</span></div></footer>${mobileNav(false,path,state)}${assistantWidget(state)}`,state)}
